import math

def round_to_sig_figs(value, sig_figs):
    if value == 0:
        return 0
    return round(value, sig_figs - int(math.floor(math.log10(abs(value)))) - 1)

result = math.sqrt(math.sqrt(100))
result_rounded = round_to_sig_figs(result, 6)
print(f"Result: {result}")
print(f"Rounded to 6 sig figs: {result_rounded}")
